var panel=Node("Panel",root.transform);panel.AddComponent<Image>();var group=panel.AddComponent<CanvasGroup>();var title=Label("Title",panel.transform,font);var points=Label("Points",panel.transform,font);var button=Node("Continue",panel.transform).AddComponent<Image>().gameObject.AddComponent<Button>();Set(popup,"overlayImage",overlay);Set(popup,"popupPanel",panel.GetComponent<RectTransform>());Set(popup,"popupCanvasGroup",group);Set(popup,"titleLabel",title);Set(popup,"pointsLabel",points);Set(popup,"continueButton",button);
