if(energy)popup.Show(20);else popup.Show(48,12,3);((Sequence)Get(popup,"_activeSequence")).Complete(true);((Sequence)Get(popup,"_pointsSequence")).Complete(true);Check(points.text==(energy?"+20 PB":"+48 PB"),"PB counter uses compact format");Check(root.activeSelf&&group.alpha==1,"Result stays visible");if(!energy){Check(((TMP_Text)Get(popup,"deliveredCountLabel")).text=="12","Delivered count");Check(((TMP_Text)Get(popup,"missedCountLabel")).text=="3","Missed count");popup.Show(0);((Sequence)Get(popup,"_activeSequence")).Complete(true);Check(!((GameObject)Get(popup,"ordersStatistics")).activeSelf,"Points-only result hides statistics");}UnityEngine.Object.DestroyImmediate(canvasObject);
}
File.WriteAllText(@"E:/SSD/GITHUB/MEQUI BREAK/tmp/result-popup-reference/render-tests.txt","PASS "+checks+" layout and result checks");EditorApplication.Exit(0);
}catch(Exception e){File.WriteAllText(@"E:/SSD/GITHUB/MEQUI BREAK/tmp/result-popup-reference/render-tests.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
